mod parser;
mod cutter;
mod output;

use parser::FieldSpec;
use cutter::TextCutter;
use output::OutputFormatter;

#[derive(Debug, Clone, Copy, ValueEnum)]
enum TrimType {
    #[value(name = "l")]
    Left,
    #[value(name = "L")]
