    RightAlt,
    #[value(name = "b")]
    Both,
    #[value(name = "B")]
    BothAlt,
}

impl TrimType {
    fn is_left(&self) -> bool {
        matches!(self, TrimType::Left | TrimType::LeftAlt | TrimType::Both | TrimType::BothAlt)
    }

    fn is_right(&self) -> bool {
        matches!(self, TrimType::Right | TrimType::RightAlt | TrimType::Both | TrimType::BothAlt)
    }
}

#[derive(Parser, Debug)]
#[command(
    name = "tuc",
    version = "1.3.0",
    about = "Cut text (or bytes) where a delimiter matches, then keep the desired parts.",
    long_about = None
)]
struct Args {
    /// Fields to keep, 1-indexed, comma separated.
    #[arg(short, long, value_name = "bounds", default_value = "1:")]
    fields: Option<String>,

    /// Same as --fields, but it keeps bytes
    #[arg(short, long, value_name = "bounds")]
    bytes: Option<String>,

    /// Same as --fields, but it keeps characters
    #[arg(short, long, value_name = "bounds")]
    characters: Option<String>,

    /// Same as --fields, but it keeps lines
    #[arg(short, long, value_name = "bounds")]
    lines: Option<String>,

    /// Delimiter used by --fields to cut the text
    #[arg(short, long, value_name = "delimiter", default_value = "\t")]
    delimiter: String,

    /// Use a regular expression as delimiter
    #[arg(short, long, value_name = "some regex")]
    regex: Option<String>,

    /// Replace the delimiter with the provided text
    #[arg(short, long, value_name = "new")]
    replace_delimiter: Option<String>,

    /// Trim the delimiter (greedy)
    #[arg(short, long, value_name = "type")]
    trim: Option<TrimType>,

    /// Generic fallback output for any field that cannot be found
    #[arg(long, value_name = "fallback")]
    fallback_oob: Option<String>,

    /// Read the input in chunks of <size> kilobytes
    #[arg(short = 'M', long, value_name = "size")]
    fixed_memory: Option<usize>,

    /// Match consecutive delimiters as if it was one
    #[arg(short, long)]
    greedy_delimiter: bool,

    /// Print only the first delimiter of a sequence
    #[arg(short, long)]
    compress_delimiter: bool,

    /// Print only lines containing the delimiter
    #[arg(short, long)]
    only_delimited: bool,

    /// Print version information
    #[arg(short = 'V', long)]
    version: bool,

    /// Line delimiter is NUL (\0), not LF (\n)
    #[arg(short, long)]
    zero_terminated: bool,

    /// Print this help and exit
    #[arg(short, long)]
    help: bool,

    /// Invert fields
    #[arg(short, long)]
    complement: bool,

    /// Print selected parts with delimiter in between
    #[arg(short, long)]
    join: bool,

    /// Don't join
    #[arg(long)]
    no_join: bool,

    /// Print fields as a JSON array of strings
    #[arg(long)]
    json: bool,

    /// Disable memory mapping
    #[arg(long)]
    no_mmap: bool,

    /// Input file path
    filepath: Option<String>,
}

fn main() -> io::Result<()> {
    let args = Args::parse();

    if args.version {
        println!("tuc 1.3.0");
        return Ok(());
    }

    if args.help {
        // Help is handled by clap
        return Ok(());
    }

    // Determine which mode to use
    let (mode, spec_str) = if let Some(ref f) = args.fields {
        ("fields", f.clone())
    } else if let Some(ref b) = args.bytes {
        ("bytes", b.clone())
    } else if let Some(ref c) = args.characters {
        ("characters", c.clone())
    } else if let Some(ref l) = args.lines {
        ("lines", l.clone())
    } else {
        ("fields", "1:".to_string())
    };

    // Parse field specification
    let field_spec = match parser::parse_field_spec(&spec_str, &args.fallback_oob) {
        Ok(spec) => spec,
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    };

    // Get the input
    let input = if let Some(filepath) = args.filepath {
        std::fs::read_to_string(&filepath)?
    } else {
        let mut buffer = String::new();
        io::stdin().read_to_string(&mut buffer)?;
        buffer
    };

    // Process the input
    match process_input(
        &input,
        mode,
        &field_spec,
        &args,
    ) {
        Ok(_) => Ok(()),
        Err(e) => {
            eprintln!("tuc: runtime error. {}", e);
            std::process::exit(1);
        }
    }
}

fn process_input(
    input: &str,
    mode: &str,
    field_spec: &FieldSpec,
    args: &Args,
) -> Result<(), String> {
    let delimiter = &args.delimiter;
    let regex_opt = args.regex.as_ref();
    let replace_delimiter = args.replace_delimiter.as_ref();
    let trim_type = args.trim;
    let greedy = args.greedy_delimiter;
    let compress = args.compress_delimiter;
    let only_delimited = args.only_delimited;
    let zero_terminated = args.zero_terminated;
    let complement = args.complement;
    let mut join = args.join;
    let no_join = args.no_join;
    let json = args.json;

    // Handle conflicting flags
    if no_join {
        join = false;
    }

    // Lines mode implies join by default
    if mode == "lines" && !no_join && replace_delimiter.is_none() {
        join = true;
    }

    // Check regex and join requirements
    if regex_opt.is_some() && join && replace_delimiter.is_none() {
        return Err("Cannot use --regex and --join without --replace-delimiter".to_string());
    }

    // Replace delimiter implies join
    if replace_delimiter.is_some() {
        join = true;
    }

    let line_sep = if zero_terminated { "\0" } else { "\n" };
    let lines: Vec<&str> = if zero_terminated {
        input.split('\0').collect()
    } else {
        input.lines().collect()
    };

    let formatter = OutputFormatter::new(json, join, replace_delimiter.map(|s| s.as_str()));

    for line in lines {
        // Skip empty output from final empty line (when input ends with separator)
        if line.is_empty() && input.ends_with(line_sep) && lines.len() > 0 {
            continue;
        }

        let parts = match mode {
            "bytes" => {
                let bytes = line.as_bytes();
                split_bytes(bytes, &field_spec, args)?
            },
            "characters" => {
                let chars: Vec<char> = line.chars().collect();
                split_chars(&chars, &field_spec, args)?
            },
            "lines" => {
                // Lines mode is different - we process all lines at once
                // So this shouldn't be called for lines mode in this loop
                vec![]
            },
            "fields" | _ => {
                split_fields(line, delimiter, regex_opt, &field_spec, args)?
            }
        };

        if only_delimited {
            // Only output if line contains delimiter or was processed successfully
            let has_delim = if let Some(ref re) = regex_opt {
                if let Ok(regex) = Regex::new(re) {
                    regex.is_match(line)
                } else {
                    line.contains(delimiter)
                }
            } else {
                line.contains(delimiter)
            };

            if !has_delim && parts.len() <= 1 && line.contains(delimiter) == false {
                continue;
            }
        }

        formatter.output_parts(&parts, line_sep)?;
    }

    // Handle lines mode separately if needed
    if mode == "lines" {
        let lines_to_process: Vec<&str> = if zero_terminated {
            input.split('\0').collect()
        } else {
            input.lines().collect()
        };

        let selected = cutter::select_lines(&lines_to_process, &field_spec)?;
        let output = if join {
            selected.join("\n")
        } else {
            selected.join("\n")
        };

        if !output.is_empty() {
            println!("{}", output);
        }
    }

    Ok(())
}

fn split_fields(
    line: &str,
    delimiter: &str,
    regex_opt: Option<&String>,
    field_spec: &FieldSpec,
    args: &Args,
) -> Result<Vec<String>, String> {
    let parts = if let Some(re_str) = regex_opt {
        let regex = Regex::new(re_str)
            .map_err(|e| format!("Invalid regex: {}", e))?;
        regex.split(line).map(|s| s.to_string()).collect::<Vec<_>>()
    } else {
        let mut parts = vec![];
        let mut remaining = line;

        if args.greedy_delimiter {
            // Match consecutive delimiters as one
            while !remaining.is_empty() {
                if remaining.starts_with(delimiter) {
                    while remaining.starts_with(delimiter) {
                        remaining = &remaining[delimiter.len()..];
                    }
                } else {
                    if let Some(pos) = remaining.find(delimiter) {
                        parts.push(remaining[..pos].to_string());
                        remaining = &remaining[pos..];
                    } else {
                        parts.push(remaining.to_string());
                        break;
                    }
                }
            }
            if remaining.is_empty() && line.ends_with(delimiter) {
                // No final part
            }
        } else {
            parts = line.split(delimiter).map(|s| s.to_string()).collect();
        }

        parts
    };

    cutter::select_fields(&parts, field_spec, args)
}

fn split_bytes(
    bytes: &[u8],
    field_spec: &FieldSpec,
    _args: &Args,
) -> Result<Vec<String>, String> {
    cutter::select_bytes(bytes, field_spec)
}

fn split_chars(
    chars: &[char],
    field_spec: &FieldSpec,
    _args: &Args,
) -> Result<Vec<String>, String> {
    cutter::select_chars(chars, field_spec)
}
