    }

    let actual_end = std::cmp::min(end, len as usize);
    let selected: String = chars[start - 1..actual_end].iter().collect();

    Ok(vec![selected])
}

pub fn select_lines(lines: &[&str], field_spec: &FieldSpec) -> Result<Vec<String>, String> {
    let mut result = Vec::new();

    for range in &field_spec.fields {
        let selected = select_line_range(lines, range)?;
        result.extend(selected);
    }

    Ok(result)
}

fn select_line_range(
    lines: &[&str],
    range: &FieldRange,
) -> Result<Vec<String>, String> {
    let len = lines.len() as isize;

    let start = match range.start {
        Some(s) if s < 0 => {
            let pos = len + s + 1;
            if pos < 1 {
                return Ok(vec![]);
            }
            pos as usize
        },
        Some(s) if s > 0 => s as usize,
        None => 1,
        _ => 1,
    };

    let end = match range.end {
        Some(e) if e < 0 => {
            let pos = len + e + 1;
            if pos < 1 {
                return Ok(vec![]);
            }
            pos as usize
        },
        Some(e) if e > 0 => e as usize,
        None => len as usize,
        _ => len as usize,
    };

    if start > end || start > (len as usize) {
        return Ok(vec![]);
    }

    let actual_end = std::cmp::min(end, len as usize);
    let selected: Vec<String> = lines[start - 1..actual_end]
        .iter()
        .map(|s| s.to_string())
        .collect();

    Ok(selected)
