use std::io;

pub struct OutputFormatter {
    json: bool,
    join: bool,
    replace_delimiter: Option<String>,
}

impl OutputFormatter {
    pub fn new(json: bool, join: bool, replace_delimiter: Option<&str>) -> Self {
        OutputFormatter {
            json,
            join,
            replace_delimiter: replace_delimiter.map(|s| s.to_string()),
        }
    }

    pub fn output_parts(&self, parts: &[String], line_sep: &str) -> Result<(), String> {
        if self.json {
            self.output_json(parts)?;
        } else if self.join || self.replace_delimiter.is_some() {
            let delimiter = self.replace_delimiter.as_ref().unwrap_or(&"\t".to_string());
            println!("{}", parts.join(delimiter));
        } else {
            for part in parts {
                println!("{}", part);
            }
        }
        Ok(())
    }

    fn output_json(&self, parts: &[String]) -> Result<(), String> {
        let json = serde_json::Value::Array(
            parts.iter().map(|s| serde_json::Value::String(s.clone())).collect()
        );
        println!("{}", json.to_string());
        Ok(())
    }
}
