use std::io::{self, Read};
use std::collections::HashMap;

mod parser;
mod cutter;
mod output;
mod regex_simple;
mod args;

use parser::FieldSpec;
use output::OutputFormatter;

fn main() -> io::Result<()> {
    let args = args::parse_args();

    if args.version {
        println!("tuc 1.3.0");
        return Ok(());
    }

    if args.help {
        print_help();
        return Ok(());
    }

    // Determine which mode to use
    let (mode, spec_str) = if let Some(ref f) = args.fields {
        ("fields", f.clone())
    } else if let Some(ref b) = args.bytes {
        ("bytes", b.clone())
    } else if let Some(ref c) = args.characters {
        ("characters", c.clone())
    } else if let Some(ref l) = args.lines {
        ("lines", l.clone())
    } else {
        ("fields", "1:".to_string())
    };

    // Parse field specification
    let field_spec = match parser::parse_field_spec(&spec_str, &args.fallback_oob) {
        Ok(spec) => spec,
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    };

    // Get the input
    let input = if let Some(filepath) = args.filepath {
        std::fs::read_to_string(&filepath)?
