        println!("tuc 1.3.0");
        return Ok(());
    }

    if args.help {
        print_help();
        return Ok(());
    }

    // Determine which mode to use
    let (mode, spec_str) = if let Some(ref f) = args.fields {
        ("fields", f.clone())
    } else if let Some(ref b) = args.bytes {
        ("bytes", b.clone())
    } else if let Some(ref c) = args.characters {
        ("characters", c.clone())
    } else if let Some(ref l) = args.lines {
        ("lines", l.clone())
    } else {
        ("fields", "1:".to_string())
    };

    // Parse field specification
    let field_spec = match parser::parse_field_spec(&spec_str, &args.fallback_oob) {
        Ok(spec) => spec,
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    };

    // Get the input
    let input = if let Some(filepath) = args.filepath {
        std::fs::read_to_string(&filepath)?
    } else {
        let mut buffer = String::new();
        io::stdin().read_to_string(&mut buffer)?;
        buffer
    };

    // Process the input
    match process_input(&input, mode, &field_spec, &args) {
        Ok(_) => Ok(()),
        Err(e) => {
            eprintln!("tuc: runtime error. {}", e);
            std::process::exit(1);
        }
    }
}

fn process_input(
    input: &str,
    mode: &str,
    field_spec: &FieldSpec,
    args: &args::Args,
) -> Result<(), String> {
    let delimiter = &args.delimiter;
    let regex_opt = args.regex.as_ref();
    let replace_delimiter = args.replace_delimiter.as_ref();
    let trim_type = args.trim;
    let greedy = args.greedy_delimiter;
    let compress = args.compress_delimiter;
    let only_delimited = args.only_delimited;
    let zero_terminated = args.zero_terminated;
    let complement = args.complement;
    let mut join = args.join;
    let no_join = args.no_join;
    let json = args.json;

    // Handle conflicting flags
    if no_join {
        join = false;
    }

    // Lines mode implies join by default
    if mode == "lines" && !no_join && replace_delimiter.is_none() {
        join = true;
    }

    // Replace delimiter implies join
    if replace_delimiter.is_some() {
        join = true;
    }

    // Check regex and join requirements
    if regex_opt.is_some() && join && replace_delimiter.is_none() {
        return Err("Cannot use --regex and --join without --replace-delimiter".to_string());
    }

    let line_sep = if zero_terminated { "\0" } else { "\n" };

    let lines: Vec<&str> = if zero_terminated {
        input.split('\0').collect()
    } else {
        input.lines().collect()
    };

    let formatter = OutputFormatter::new(json, join, replace_delimiter.map(|s| s.as_str()));

    if mode == "lines" {
        let selected = cutter::select_lines(&lines, &field_spec)?;
        let output = selected.join("\n");
        if !output.is_empty() {
            println!("{}", output);
        }
    } else {
        for line in lines {
            // Skip processing if last line is empty and input ends with separator
            if line.is_empty() && input.ends_with(line_sep) && !input.is_empty() {
                let remaining = if zero_terminated {
                    input.trim_end_matches('\0')
                } else {
                    input.trim_end_matches('\n')
                };
                if remaining.is_empty() || remaining.ends_with('\n') || remaining.ends_with('\0') {
                    continue;
                }
            }

            let parts = match mode {
                "bytes" => split_bytes(line.as_bytes(), &field_spec, args)?,
                "characters" => split_chars(line, &field_spec, args)?,
                "fields" | _ => split_fields(line, delimiter, regex_opt, &field_spec, args)?,
            };

            if only_delimited {
                let has_delim = if let Some(ref re) = regex_opt {
                    regex_simple::matches(re, line).is_ok()
                } else {
                    line.contains(delimiter)
                };

                if !has_delim {
                    continue;
                }
            }

            formatter.output_parts(&parts, line_sep)?;
        }
    }

    Ok(())
}

fn split_fields(
    line: &str,
    delimiter: &str,
    regex_opt: Option<&String>,
    field_spec: &FieldSpec,
    args: &args::Args,
) -> Result<Vec<String>, String> {
    let parts = if let Some(re_str) = regex_opt {
        regex_simple::split(re_str, line)?
    } else {
        let mut parts = vec![];

        if args.greedy_delimiter {
            let mut remaining = line;
            while !remaining.is_empty() {
                if remaining.starts_with(delimiter) {
                    while remaining.starts_with(delimiter) {
                        remaining = &remaining[delimiter.len()..];
                    }
                } else {
                    if let Some(pos) = remaining.find(delimiter) {
                        parts.push(remaining[..pos].to_string());
                        remaining = &remaining[pos..];
                    } else {
                        parts.push(remaining.to_string());
                        break;
                    }
                }
            }
        } else {
            parts = line.split(delimiter).map(|s| s.to_string()).collect();
        }

        parts
    };

    cutter::select_fields(&parts, field_spec, args)
}

fn split_bytes(
    bytes: &[u8],
    field_spec: &FieldSpec,
    _args: &args::Args,
) -> Result<Vec<String>, String> {
    cutter::select_bytes(bytes, field_spec)
}

fn split_chars(
    line: &str,
    field_spec: &FieldSpec,
    _args: &args::Args,
) -> Result<Vec<String>, String> {
    let chars: Vec<char> = line.chars().collect();
    cutter::select_chars(&chars, field_spec)
}

fn print_help() {
    println!("tuc 1.3.0");
    println!("Cut text (or bytes) where a delimiter matches, then keep the desired parts.");
    println!();
    println!("USAGE:");
    println!("    tuc [FLAGS] [OPTIONS] < input");
    println!("    tuc [FLAGS] [OPTIONS] filepath");
    println!();
    println!("FLAGS:");
    println!("    -g, --greedy-delimiter        Match consecutive delimiters as if it was one");
    println!("    -p, --compress-delimiter      Print only the first delimiter of a sequence");
    println!("    -s, --only-delimited          Print only lines containing the delimiter");
    println!("    -V, --version                 Print version information");
    println!("    -z, --zero-terminated         Line delimiter is NUL (\\0), not LF (\\n)");
    println!("    -h, --help                    Print this help and exit");
    println!("    -m, --complement              Invert fields (e.g. '2' becomes '1,3:')");
    println!("    -j, --(no-)join               Print selected parts with delimiter in between");
    println!("    --json                        Print fields as a JSON array of strings");
    println!("    --no-mmap                     Disable memory mapping");
    println!();
    println!("OPTIONS:");
    println!("    -f, --fields <bounds>         Fields to keep, 1-indexed, comma separated.");
    println!("                                  Use colon (:) to match a range (inclusive).");
    println!("                                  Use equal (=) to apply out of bound fallback.");
    println!("                                  Fields can be negative (-1 is the last field).");
    println!("                                  [default: 1:]");
    println!();
    println!("    -b, --bytes <bounds>          Same as --fields, but it keeps bytes");
    println!("    -c, --characters <bounds>     Same as --fields, but it keeps characters");
    println!("    -l, --lines <bounds>          Same as --fields, but it keeps lines");
    println!("    -d, --delimiter <delimiter>   Delimiter used by --fields to cut the text");
    println!("                                  [default: \\t]");
    println!("    -e, --regex <some regex>      Use a regular expression as delimiter");
    println!("    -r, --replace-delimiter <new> Replace the delimiter with the provided text.");
    println!("                                  Implies --join");
    println!("    -t, --trim <type>             Trim the delimiter (greedy). Valid values are");
    println!("                                  (l|L)eft, (r|R)ight, (b|B)oth");
    println!("        --fallback-oob <fallback> Generic fallback output for any field that");
    println!("                                  cannot be found (oob stands for out of bound).");
    println!("    -M, --fixed-memory <size>     Read the input in chunks of <size> kilobytes.");
}
