                if i < argv.len() {
                    args.characters = Some(argv[i].clone());
                }
            }
            "-l" | "--lines" => {
                i += 1;
                if i < argv.len() {
                    args.lines = Some(argv[i].clone());
                }
            }
            "-d" | "--delimiter" => {
                i += 1;
                if i < argv.len() {
                    args.delimiter = argv[i].clone();
                }
            }
            "-e" | "--regex" => {
                i += 1;
                if i < argv.len() {
                    args.regex = Some(argv[i].clone());
                }
            }
            "-r" | "--replace-delimiter" => {
                i += 1;
                if i < argv.len() {
                    args.replace_delimiter = Some(argv[i].clone());
                }
            }
            "-t" | "--trim" => {
                i += 1;
                if i < argv.len() {
                    args.trim = match argv[i].as_str() {
                        "l" | "L" => Some(TrimType::Left),
                        "r" | "R" => Some(TrimType::Right),
                        "b" | "B" => Some(TrimType::Both),
                        _ => None,
                    };
                }
            }
            "--fallback-oob" => {
                i += 1;
                if i < argv.len() {
                    args.fallback_oob = Some(argv[i].clone());
                }
            }
            "-M" | "--fixed-memory" => {
                i += 1;
                if i < argv.len() {
                    if let Ok(size) = argv[i].parse::<usize>() {
                        args.fixed_memory = Some(size);
                    }
                }
            }
            arg => {
                // Check if it's a filepath (last argument not starting with -)
                if !arg.starts_with('-') {
                    args.filepath = Some(arg.to_string());
                }
            }
        }

        i += 1;
    }

    args
}
