    if pattern == "[0-9]+" {
        let mut len = 0;
        for c in text.chars() {
            if c.is_numeric() {
                len += c.len_utf8();
            } else {
                break;
            }
        }
        if len > 0 {
            return Some(len);
        }
    }

    // Handle other common patterns like [a-z]+, [A-Z]+, etc.
    if pattern.starts_with("[a-z]+") {
        let mut len = 0;
        for c in text.chars() {
            if c.is_ascii_lowercase() {
                len += c.len_utf8();
            } else {
                break;
            }
        }
        if len > 0 {
            return Some(len);
        }
    }

    if pattern.starts_with("[A-Z]+") {
        let mut len = 0;
        for c in text.chars() {
            if c.is_ascii_uppercase() {
                len += c.len_utf8();
            } else {
                break;
            }
        }
        if len > 0 {
            return Some(len);
        }
    }

    // Try literal match
    if text.starts_with(pattern) {
        return Some(pattern.len());
    }

    None
}

