use std::io;

pub struct OutputFormatter {
    json: bool,
    join: bool,
    replace_delimiter: Option<String>,
}

impl OutputFormatter {
    pub fn new(json: bool, join: bool, replace_delimiter: Option<&str>) -> Self {
        OutputFormatter {
            json,
            join,
            replace_delimiter: replace_delimiter.map(|s| s.to_string()),
        }
    }

    pub fn output_parts(&self, parts: &[String], line_sep: &str) -> Result<(), String> {
        if self.json {
            self.output_json(parts)?;
        } else if self.join || self.replace_delimiter.is_some() {
            let delimiter = self.replace_delimiter.as_ref().map(|s| s.as_str()).unwrap_or("\t");
            println!("{}", parts.join(delimiter));
        } else {
            for part in parts {
                println!("{}", part);
            }
        }
        Ok(())
    }

    fn output_json(&self, parts: &[String]) -> Result<(), String> {
        // Manually build JSON array
        let mut json = String::from("[");
        for (i, part) in parts.iter().enumerate() {
            if i > 0 {
                json.push(',');
            }
            json.push('"');
            for c in part.chars() {
                match c {
                    '"' => json.push_str("\\\""),
                    '\\' => json.push_str("\\\\"),
                    '\n' => json.push_str("\\n"),
                    '\r' => json.push_str("\\r"),
                    '\t' => json.push_str("\\t"),
                    _ => json.push(c),
                }
            }
            json.push('"');
        }
        json.push(']');
        println!("{}", json);
        Ok(())
    }
}
EOF

