pub struct OutputFormatter {
    json: bool,
    join: bool,
    join_delimiter: String,
}

impl OutputFormatter {
    pub fn new(json: bool, join: bool, join_delimiter: &str) -> Self {
        OutputFormatter {
            json,
            join,
            join_delimiter: join_delimiter.to_string(),
        }
    }

    pub fn output_parts(&self, parts: &[String]) -> Result<(), String> {
        if self.json {
            self.output_json(parts)?;
        } else if self.join {
            println!("{}", parts.join(&self.join_delimiter));
        } else {
            // Default: concatenate all parts on one line
            println!("{}", parts.join(""));
        }
        Ok(())
    }

    fn output_json(&self, parts: &[String]) -> Result<(), String> {
        // Manually build JSON array
        let mut json = String::from("[");
        for (i, part) in parts.iter().enumerate() {
            if i > 0 {
                json.push(',');
            }
            json.push('"');
            for c in part.chars() {
                match c {
                    '"' => json.push_str("\\\""),
                    '\\' => json.push_str("\\\\"),
                    '\n' => json.push_str("\\n"),
                    '\r' => json.push_str("\\r"),
                    '\t' => json.push_str("\\t"),
                    _ => json.push(c),
                }
            }
            json.push('"');
        }
        json.push(']');
        println!("{}", json);
        Ok(())
    }
}
