use std::collections::HashMap;

#[derive(Debug, Clone)]
pub struct FieldSpec {
    pub format: Option<String>,
    pub fields: Vec<FieldRange>,
    pub default_fallback: Option<String>,
}

#[derive(Debug, Clone)]
pub struct FieldRange {
    pub start: Option<isize>,
    pub end: Option<isize>,
    pub fallback: Option<String>,
}

pub fn parse_field_spec(spec: &str, default_fallback: &Option<String>) -> Result<FieldSpec, String> {
    // Check if this is a format string (contains { and })
    if spec.contains('{') || spec.contains('}') {
        return parse_format_spec(spec, default_fallback);
    }

    let mut fields = Vec::new();

    // Parse comma-separated field specifications
    for field_str in spec.split(',') {
        let field_str = field_str.trim();

        if field_str.is_empty() {
            continue;
        }

        // Check for fallback syntax: field=fallback
        let (range_str, fallback) = if let Some(eq_pos) = field_str.find('=') {
            (&field_str[..eq_pos], Some(field_str[eq_pos + 1..].to_string()))
        } else {
            (field_str, None)
        };

        // Parse range: "start:end" or just "number"
        if let Some(colon_pos) = range_str.find(':') {
            let start_str = &range_str[..colon_pos];
            let end_str = &range_str[colon_pos + 1..];

            let start = if start_str.is_empty() {
                None
            } else {
                Some(start_str.parse::<isize>()
                    .map_err(|_| format!("Invalid field number: {}", start_str))?)
            };

            let end = if end_str.is_empty() {
                None
            } else {
                Some(end_str.parse::<isize>()
                    .map_err(|_| format!("Invalid field number: {}", end_str))?)
            };

            fields.push(FieldRange { start, end, fallback });
        } else {
            // Single field
            let num = range_str.parse::<isize>()
                .map_err(|_| format!("Invalid field number: {}", range_str))?;

            fields.push(FieldRange {
                start: Some(num),
                end: Some(num),
                fallback,
            });
        }
    }

    Ok(FieldSpec {
        format: None,
        fields,
        default_fallback: default_fallback.clone(),
    })
}

fn parse_format_spec(spec: &str, default_fallback: &Option<String>) -> Result<FieldSpec, String> {
    // Extract field numbers from format string
    let mut fields = Vec::new();
    let mut used_fields = std::collections::HashSet::new();

    // Find all {N} patterns
    let mut chars = spec.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '{' {
            if chars.peek() == Some(&'{') {
                // Escaped brace
                chars.next();
                continue;
            }

            // Read field number
            let mut num_str = String::new();
            while let Some(&ch) = chars.peek() {
                if ch == '}' {
                    chars.next();
                    break;
                }
                num_str.push(chars.next().unwrap());
            }

            if !num_str.is_empty() {
                let field_num = num_str.parse::<isize>()
                    .map_err(|_| format!("Invalid field number in format: {}", num_str))?;
                used_fields.insert(field_num);
            }
        }
    }

    // Convert used fields to ranges
    for field_num in used_fields.iter() {
        fields.push(FieldRange {
            start: Some(*field_num),
            end: Some(*field_num),
            fallback: None,
        });
    }

    // Sort by start position
    fields.sort_by_key(|f| f.start);

    Ok(FieldSpec {
        format: Some(spec.to_string()),
        fields,
        default_fallback: default_fallback.clone(),
    })
}
