) -> Result<Vec<String>, String> {
    let mut result = Vec::new();

    let len = parts.len() as isize;

    let start = match range.start {
        Some(s) if s < 0 => {
            let pos = len + s + 1;
            if pos < 1 {
                return Err(format!("Out of bounds: {}", s));
            }
            pos as usize
        },
        Some(s) if s > 0 => s as usize,
        None => 1,
        _ => return Err("Invalid range start".to_string()),
    };

    let end = match range.end {
        Some(e) if e < 0 => {
            let pos = len + e + 1;
            if pos < 1 {
                return Err(format!("Out of bounds: {}", e));
            }
            pos as usize
        },
        Some(e) if e > 0 => e as usize,
        None => len as usize,
        _ => return Err("Invalid range end".to_string()),
    };

    if start > end {
        return Err(format!("Invalid range: {}:{}", start, end));
    }

    for i in start..=end {
        if i > 0 && (i as isize) <= len {
            result.push(parts[i - 1].clone());
        } else {
            // Out of bounds - use fallback
            if let Some(ref fallback) = range.fallback {
                result.push(fallback.clone());
            } else if let Some(ref default_fb) = default_fallback {
                result.push(default_fb.clone());
            } else {
                // Error on out of bounds if no fallback
                return Err(format!("Out of bounds: {}", i));
            }
        }
    }

    Ok(result)
}

fn select_fields_with_format(
    parts: &[String],
    format_str: &str,
    field_spec: &FieldSpec,
    _args: &crate::args::Args,
) -> Result<Vec<String>, String> {
    // Build a map of field numbers to values
    let mut field_map = std::collections::HashMap::new();

    let len = parts.len() as isize;

    for range in &field_spec.fields {
        let start = match range.start {
            Some(s) if s < 0 => (len + s + 1) as usize,
            Some(s) if s > 0 => s as usize,
            None => 1,
            _ => continue,
        };

        let end = match range.end {
            Some(e) if e < 0 => (len + e + 1) as usize,
            Some(e) if e > 0 => e as usize,
            None => len as usize,
            _ => continue,
        };

        for i in start..=end {
            if i > 0 && (i as isize) <= len {
                field_map.insert(i as isize, parts[i - 1].clone());
            }
        }
    }

    // Format the output string
    let mut output = String::new();
    let mut chars = format_str.chars().peekable();

    while let Some(c) = chars.next() {
        if c == '{' {
            if chars.peek() == Some(&'{') {
                // Escaped opening brace
                output.push('{');
                chars.next();
                continue;
            }

            // Read field number
            let mut num_str = String::new();
            while let Some(&ch) = chars.peek() {
                if ch == '}' {
                    chars.next();
                    break;
                }
                num_str.push(chars.next().unwrap());
            }

            if !num_str.is_empty() {
                if let Ok(field_num) = num_str.parse::<isize>() {
                    if let Some(value) = field_map.get(&field_num) {
                        output.push_str(value);
                    } else {
                        // Field not found - use fallback
                        if let Some(ref default_fb) = field_spec.default_fallback {
                            output.push_str(default_fb);
                        }
                    }
                }
            }
        } else if c == '}' {
            if chars.peek() == Some(&'}') {
                // Escaped closing brace
                output.push('}');
                chars.next();
            } else {
                output.push(c);
            }
        } else {
            output.push(c);
        }
    }

    Ok(vec![output])
}

pub fn select_bytes(bytes: &[u8], field_spec: &FieldSpec) -> Result<Vec<String>, String> {
    let mut result = Vec::new();

    for range in &field_spec.fields {
        let selected = select_byte_range(bytes, range)?;
        result.extend(selected);
    }

    Ok(result)
}

fn select_byte_range(
    bytes: &[u8],
    range: &FieldRange,
) -> Result<Vec<String>, String> {
    let len = bytes.len() as isize;

    let start = match range.start {
        Some(s) if s < 0 => {
            let pos = len + s + 1;
            if pos < 1 {
                return Ok(vec![]);
            }
            pos as usize
        },
        Some(s) if s > 0 => s as usize,
        None => 1,
        _ => 1,
    };

    let end = match range.end {
        Some(e) if e < 0 => {
            let pos = len + e + 1;
            if pos < 1 {
                return Ok(vec![]);
            }
            pos as usize
        },
        Some(e) if e > 0 => e as usize,
        None => len as usize,
        _ => len as usize,
    };

    if start > end || start > (len as usize) {
        return Ok(vec![]);
    }

    let actual_end = std::cmp::min(end, len as usize);
    let selected = &bytes[start - 1..actual_end];

    Ok(vec![String::from_utf8_lossy(selected).to_string()])
}

pub fn select_chars(chars: &[char], field_spec: &FieldSpec) -> Result<Vec<String>, String> {
    let mut result = Vec::new();

    for range in &field_spec.fields {
        let selected = select_char_range(chars, range)?;
        result.extend(selected);
    }

    Ok(result)
}

fn select_char_range(
    chars: &[char],
    range: &FieldRange,
) -> Result<Vec<String>, String> {
    let len = chars.len() as isize;

    let start = match range.start {
        Some(s) if s < 0 => {
            let pos = len + s + 1;
            if pos < 1 {
                return Ok(vec![]);
            }
            pos as usize
        },
        Some(s) if s > 0 => s as usize,
        None => 1,
        _ => 1,
    };

    let end = match range.end {
        Some(e) if e < 0 => {
            let pos = len + e + 1;
            if pos < 1 {
                return Ok(vec![]);
            }
            pos as usize
        },
        Some(e) if e > 0 => e as usize,
        None => len as usize,
        _ => len as usize,
    };

    if start > end || start > (len as usize) {
        return Ok(vec![]);
    }

    let actual_end = std::cmp::min(end, len as usize);
    let selected: String = chars[start - 1..actual_end].iter().collect();

    Ok(vec![selected])
}

pub fn select_lines(lines: &[&str], field_spec: &FieldSpec) -> Result<Vec<String>, String> {
    let mut result = Vec::new();

    for range in &field_spec.fields {
        let selected = select_line_range(lines, range)?;
        result.extend(selected);
    }

    Ok(result)
}

fn select_line_range(
    lines: &[&str],
    range: &FieldRange,
) -> Result<Vec<String>, String> {
    let len = lines.len() as isize;

    let start = match range.start {
        Some(s) if s < 0 => {
            let pos = len + s + 1;
            if pos < 1 {
                return Ok(vec![]);
            }
            pos as usize
        },
        Some(s) if s > 0 => s as usize,
        None => 1,
        _ => 1,
    };

    let end = match range.end {
        Some(e) if e < 0 => {
            let pos = len + e + 1;
            if pos < 1 {
                return Ok(vec![]);
            }
            pos as usize
        },
        Some(e) if e > 0 => e as usize,
        None => len as usize,
        _ => len as usize,
    };

    if start > end || start > (len as usize) {
        return Ok(vec![]);
    }

    let actual_end = std::cmp::min(end, len as usize);
    let selected: Vec<String> = lines[start - 1..actual_end]
        .iter()
        .map(|s| s.to_string())
        .collect();

    Ok(selected)
}
